// Sidebar group labels for nested folders. Starlight names an autogenerated group after its folder
// ("sensors"); a `_group.yml` file in the folder gives it a Chinese label instead:
//
//   label: 传感器
//   collapsed: false      # optional
//
// The file lives next to the pages it labels, so adding a folder never touches a central file.
import { defineRouteMiddleware } from "@astrojs/starlight/route-data";
import { parse } from "yaml";

const files = import.meta.glob("/src/content/docs/**/_group.yml", { query: "?raw", import: "default", eager: true });

const groups = new Map();
for (const [path, raw] of Object.entries(files)) {
  const dir = path.replace(/^\/src\/content\/docs\//, "").replace(/\/_group\.yml$/, "").toLowerCase();
  const meta = parse(String(raw)) ?? {};
  groups.set(dir, meta);
}

function firstHref(group) {
  for (const e of group.entries) {
    if (e.type === "link") return e.href;
    const inner = firstHref(e);
    if (inner) return inner;
  }
  return null;
}

function relabel(entries, depth) {
  for (const entry of entries) {
    if (entry.type !== "group") continue;
    if (depth > 0) {
      const href = firstHref(entry);
      const dir = href ? href.split("/").filter(Boolean).slice(0, depth + 1).join("/") : "";
      const meta = groups.get(dir);
      if (typeof meta?.label === "string") entry.label = meta.label;
      if (typeof meta?.collapsed === "boolean") entry.collapsed = meta.collapsed;
    }
    relabel(entry.entries, depth + 1);
  }
}

export const onRequest = defineRouteMiddleware((context) => {
  relabel(context.locals.starlightRoute.sidebar, 0);
});
